 effect(tex,points,alpha=1,additive=true){const v=this.view,p=points.reduce((a,b)=>a.map((n,i)=>n+b[i]/4),[0,0,0]),by=p[1]-this.curve*((p[0]-this.center[0])**2+(p[2]-this.center[1])**2);this.transparent.push({effect:true,args:[tex,points,alpha,additive],depth:-(v[2]*p[0]+v[6]*by+v[10]*p[2]+v[14])});}
 drawEffect(tex,points,alpha,additive){const g=this.gl;this.effectProgram??=program(g,effectVS,effectFS);this.effectBuffer??=g.createBuffer();const p=this.effectProgram;this.common(p);this.uniform(p,'uAlpha',alpha);const data=effectGrid(points);g.bindBuffer(g.ARRAY_BUFFER,this.effectBuffer);g.bufferData(g.ARRAY_BUFFER,new Float32Array(data),g.DYNAMIC_DRAW);for(const[name,size,offset]of[['aPos',3,0],['aUV',2,12]]){const l=g.getAttribLocation(p,name);g.enableVertexAttribArray(l);g.vertexAttribPointer(l,size,g.FLOAT,false,20,offset);}g.activeTexture(g.TEXTURE0);g.bindTexture(g.TEXTURE_2D,tex);g.uniform1i(g.getUniformLocation(p,'uTex'),0);g.blendFunc(g.SRC_ALPHA,additive?g.ONE:g.ONE_MINUS_SRC_ALPHA);g.drawArrays(g.TRIANGLES,0,data.length/5);g.blendFunc(g.SRC_ALPHA,g.ONE_MINUS_SRC_ALPHA);this.calls++;}
